#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);

import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {validateMessage} from './ws/validation.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, connectClient, startEngineWith, stopEngines} from './wsTestSupport.js';

type WireFrame = {
  type: string;
  code?: string;
  conversations?: Array<Record<string, unknown>>;
};

const historyEnabled = {history: {enabled: true}};

const waitForListResponse = async (url: string, request: unknown): Promise<WireFrame[]> => {
  const client = connectClient(url, 'token');
  const frames: WireFrame[] = [];

  return new Promise<WireFrame[]>((resolve, reject) => {
    const timeout = setTimeout(() => {
      client.terminate();
      reject(
        new Error(`Timed out waiting for a response to ${JSON.stringify(request)}; received ${JSON.stringify(frames)}`)
      );
    }, 100);

    client.on('error', reject);
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (frame.type === 'connected') {
        client.send(JSON.stringify(request));
        return;
      }
      frames.push(frame);
      if (frame.type === 'conversation_list' || frame.type === 'error') {
        clearTimeout(timeout);
        resolve(frames);
      }
    });
  });
};

describe('conversation list acceptance contract', () => {
  afterEach(async () => {
    await stopEngines();
  });

  it('accepts list_conversations and validates its limit and composite before cursor', () => {
    expect(validateMessage({type: 'list_conversations'})).toEqual({
      valid: true,
      data: {type: 'list_conversations', limit: undefined, before: undefined},
    });

    for (const message of [
      {type: 'list_conversations', limit: 0},
      {type: 'list_conversations', limit: 201},
      {type: 'list_conversations', limit: 1.5},
      {type: 'list_conversations', limit: '10'},
      {type: 'list_conversations', before: {updatedAt: '2026-10-27T12:00:00.000Z'}},
      {type: 'list_conversations', before: {sessionId: 's1'}},
    ]) {
      const result = validateMessage(message);
      expect(result.valid).toBe(false);
      if (!result.valid) expect(result.error).toMatch(/limit|before/);
    }
  });

  it('answers the authenticated user’s list with summaries, ignoring a frame userId', async () => {
    const store = new InMemorySessionStore();
    const newest = store.create('newest', 'u1');
    newest.entries.push({role: 'user', content: 'newest', timestamp: '2026-12-01T00:00:00.000Z'});
    const older = store.create('older', 'u1');
    older.entries.push({role: 'user', content: 'older', timestamp: '2026-11-01T00:00:00.000Z'});
    store.create('another-user', 'u2');

    const {url} = await startEngineWith({
      sessionStore: store,
      orchestrator: answeringOrchestrator,
      wsAuth: async () => ({id: 'u1'}),
      ...(historyEnabled as never),
    });
    const [frame] = await waitForListResponse(url, {type: 'list_conversations', userId: 'u2'});

    expect(frame).toMatchObject({type: 'conversation_list'});
    expect(frame.conversations).toHaveLength(3);
    expect(frame.conversations?.map(conversation => conversation.sessionId)).toEqual([
      'newest',
      'older',
      expect.any(String),
    ]);
    expect(
      frame.conversations?.every(
        conversation => Object.keys(conversation).sort().join(',') === 'createdAt,entryCount,sessionId,updatedAt'
      )
    ).toBe(true);
    expect(
      frame.conversations?.every(
        conversation =>
          typeof conversation.createdAt === 'string' &&
          typeof conversation.updatedAt === 'string' &&
          new Date(conversation.createdAt).toISOString() === conversation.createdAt &&
          new Date(conversation.updatedAt).toISOString() === conversation.updatedAt
      )
    ).toBe(true);
  });

  it('refuses the list with UNSUPPORTED when history is not enabled', async () => {
    const store = new InMemorySessionStore();
    const {url} = await startEngineWith({sessionStore: store, orchestrator: answeringOrchestrator});

    await expect(waitForListResponse(url, {type: 'list_conversations'})).resolves.toEqual([
      {type: 'error', code: 'UNSUPPORTED', message: expect.any(String)},
    ]);
  });
});

void HAL_WS_SUBPROTOCOL;
- On reconnection success, any queued `user_message` messages MUST be flushed immediately.
- On reconnection, the client MUST clear its local entries array and SHOULD send `?sessionId=` with the id from its last `connected` frame. When the server has resume enabled and the conversation is the user's own, it answers `resumed: true` and replays the conversation; otherwise the client is starting a new session.
- An entry still streaming when its conversation is resumed is replayed with `isStreaming: false` and `truncated: true`: the rest of its turn streams to the connection that started it, so this one would wait for a commit that never comes ([validated by: replays an entry whose turn is still running as finished and truncated, leaving the stored entry as it is](../../src/transport/sessionResume.test.ts#L364)).
- With the server's `latest` option, a client that has lost the id, after a page refresh for instance, MAY connect without one and still rejoin its user's most recent conversation, and sends `?new=1` to start a new conversation instead ([validated by: with latest on, rejoins the most recently active session of a user whose connect names none](../../src/transport/sessionResume.test.ts#L428), [validated by: with latest on, starts a new session for a user with none, and on ?new=1 even when one exists](../../src/transport/sessionResume.test.ts#L445)).

After 5 failed attempts, the client MUST stop reconnecting and report a disconnected state.

## 12. Security Considerations

- Access tokens are transmitted in the `Sec-WebSocket-Protocol` request header, which keeps them out of the request line and so out of a URL-based access log. They are not hidden from logging in general: an ingress or proxy that captures request headers records them, as it records an `Authorization` header, so header capture must redact `Sec-WebSocket-Protocol` too.
- The server answers with the `hal.v1` marker, so the token is never written into the 101 response headers or held as the connected socket's `protocol` property. An offer without the marker is answered with no subprotocol, so no offered value is ever echoed.
- No offered subprotocol value is written to the engine's own log at any level. Every place a credential exists during a connection - request headers, the socket's and the session's `authHeaders`, and the tool context - is listed in [the subprotocol marker spec](../hal-engine-subprotocol-marker/spec.md#where-a-credential-exists).
- Message content is validated at the server boundary. Content exceeding 10,000 characters is rejected.
- The server validates all incoming messages against known types. Unrecognized types receive an `INVALID_MESSAGE` error.

